head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.secugrpId = 'PF';
scwin.secugrpNm = '상장형수익증권';
scwin.vSearchDate = "";
scwin.pJobTitl = js_jobtitl;
// var listBzTpCd = LIST_BZ_TP_CD_813; // PF 매매거래정지
scwin.loding1, scwin.loding2, scwin.loding3, scwin.loding4, scwin.loding5, scwin.loding6;
scwin.fn_GetPar, scwin.fn_SetPar;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        const vCurDate = $c.ut.cGetToday("yyyymmdd");
        edt_ConfirmDate.setValue(vCurDate);
        await scwin.listSync();
        txb_cnt1.setValue(dts_List1.getRowCount() + " 건");
        txb_cnt2.setValue(dts_List2.getRowCount() + " 건");
        txb_cnt3.setValue(dts_List3.getRowCount() + " 건");
        txb_cnt4.setValue(dts_List4.getRowCount() + " 건");
        txb_cnt5.setValue(dts_List5.getRowCount() + " 건");
        txb_cnt6.setValue(dts_List6.getRowCount() + " 건");
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF09350.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_Excel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Excel_onclick = function() {
    try {
        $c.stf.doLogSave("ULDSTF09350.xml", SCREN_PROCS_TP_CD_07);
        scwin.excelDown();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF09350.btn_Excel_onclick" });
    }
};

/**
