///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name listDtl
 * @description list Dtl 처리
 * @param {*} type type
 * @param {*} nowOld nowOld
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listDtl = async function(type, nowOld) {
    let urlcond = '';
    let datasetId = "";
    urlcond += "&BAS_DD=" + edt_ConfirmDate.getValue();
    urlcond += "&SECUGRP_ID=" + scwin.secugrpId;
    if (nowOld === "OLD") {
        if (type === "01") {
            // 최초적출
            urlcond += "&ETP_INVSTWARN_CD=" + "01";
            let url_list = "/pf/InvstwarnClose.do?method=selectOldList";
            datasetId = dts_List1;
        } else if (type === "02") {
            // 지정예고
            urlcond += "&ETP_INVSTWARN_CD=" + "02";
            let url_list = "/pf/InvstwarnClose.do?method=selectOldList";
            datasetId = dts_List2;
        } else if (type === "04") {
            // 지정연장
            urlcond += "&ETP_INVSTWARN_CD=" + "04";
            let url_list = "/pf/InvstwarnClose.do?method=selectOldList";
            datasetId = dts_List3;
        } else if (type === "03") {
            // 지정
            urlcond += "&ETP_INVSTWARN_CD=" + "03";
            let url_list = "/pf/InvstwarnClose.do?method=selectOldList";
            datasetId = dts_List4;
        } else if (type === "05") {
            // 지정해제
            urlcond += "&ETP_INVSTWARN_CD=" + "05";
            let url_list = "/pf/InvstwarnClose.do?method=selectOldList";
            datasetId = dts_List5;
        } else if (type === "06") {
            // 매매거래정지, 매매거래정지 해제, 매매거래정지 및 해제
            urlcond += "&ETP_INVSTWARN_CD=" + "06";
            let url_list = "/pf/InvstwarnClose.do?method=selectOldList";
            datasetId = dts_List6;
        }
    } else {
        if (type === "01") {
            // 최초적출
            let url_list = "/pf/InvstwarnClose.do?method=selectFirstDetect";
            datasetId = dts_List1;
        } else if (type === "02") {
            // 지정예고
            let url_list = "/pf/InvstwarnClose.do?method=selectNoti";
            datasetId = dts_List2;
        } else if (type === "04") {
            // 지정연장
            let url_list = "/pf/InvstwarnClose.do?method=selectExtn";
            datasetId = dts_List3;
        } else if (type === "03") {
            // 지정
            let url_list = "/pf/InvstwarnClose.do?method=selectDesign";
            datasetId = dts_List4;
        } else if (type === "05") {
            // 지정해제
            let url_list = "/pf/InvstwarnClose.do?method=selectRelease";
            datasetId = dts_List5;
        } else if (type === "06") {
            // 매매거래정지, 매매거래정지 해제, 매매거래정지 및 해제
            urlcond += "&LIST_BZ_TP_CD=" + LIST_BZ_TP_CD_813;
            datasetId = dts_List6;
        }
    }
    url_list += urlcond;
    url_list += "&SCREN_ID=" + "ULDSTF09350.xml";
    url_list += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    const sbmOptions = {
        id : "sbm_datasetId",
        action : "/pf/InvstwarnClose.do",
        ref : "",
        target : "datasetId=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

