    dts_Cls.setCellData(1, "SECUGRP_ID", scwin.secugrpId);
    trs_revw.KeyName = "toinb_dataid4";
    const sbmOptions = {
        id : "sbm_trs_revw",
        action : "/pf/InvstwarnClose.do",
        ref : "dts_Cls",
        target : "trs_revw=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
};

