/**
 * @method
 * @name getJungBoBatch
 * @description 시장정보 배치실행 여부 가져오기
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.getJungBoBatch = async function() {
    const sbmOptions = {
        id : "sbm_dts_batYn",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_batYn=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    txb_ClsDtl.setValue(dts_batYn.getCellData(1, "CLS_YN"));
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name dateErrCheck
 * @description date Err Check 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dateErrCheck = async function() {
    if (edt_ConfirmDate.getValue() === "" || edt_ConfirmDate.Text.length < 8) {
        await $c.win.alert("마감일을 입력하세요.");
        edt_ConfirmDate.focus();
        return true;
    }
};

/**
 * @method
 * @name listSync
 * @description list Sync 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listSync = async function() {
    if (await scwin.dateErrCheck()) {
        return;
    }
    loading1 = false;
    loading2 = false;
    loading3 = false;
    loading4 = false;
    loading5 = false;
    loading6 = false;
    let nowOld = "NOW";
    let curDd = $c.ut.cGetToday("yyyymmdd");
    let searchDate = edt_ConfirmDate.getValue();
    // 마감일이 오늘이 아니면 이력조회
    if (curDd !== searchDate) {
        nowOld = "OLD";
    }
    await scwin.clslogSync();
    // 팀장 마감이 되었다면 이력조회
    const apprvEmpNm = txb_APPROVR_EMP_NM.getValue();
    if (apprvEmpNm.length > 0) {
        nowOld = "OLD";
    }
    scwin.vSearchDate = edt_ConfirmDate.getValue();
    await scwin.getJungBoBatch();
    await scwin.listDtl("01", nowOld);
    await scwin.listDtl("02", nowOld);
    await scwin.listDtl("03", nowOld);
    await scwin.listDtl("04", nowOld);
    await scwin.listDtl("05", nowOld);
    await scwin.listDtl("06", nowOld);
};

/**
 * @method
 * @name excelDown
 * @description 정보를 excel로 다운 받는다.
 * @returns {void}
 * @hidden N
 */
scwin.excelDown = function() {
    const today = $c.ut.cGetToday("yyyymmddhhmmss");
    // 파일형식 today_화면명.xls
    const xls_path = $c.session.getExcelDownPath() + today + scwin.secugrpNm + "투자유의종목마감.xls";
    $c.data.saveExcel(grd_List1, "최초적출", false, false, false, xls_path);
    if (dts_List2.getRowCount() > 0) {
        $c.data.downloadGridViewExcel(grd_List2, {fileName: "지정예고", sheetName: xls_path, type: 40});
    }
    if (dts_List3.getRowCount() > 0) {
        $c.data.downloadGridViewExcel(grd_List3, {fileName: "지정연장", sheetName: xls_path, type: 40});
    }
    if (dts_List4.getRowCount() > 0) {
        $c.data.downloadGridViewExcel(grd_List4, {fileName: "지정", sheetName: xls_path, type: 40});
    }
    if (dts_List5.getRowCount() > 0) {
        $c.data.downloadGridViewExcel(grd_List5, {fileName: "지정해제", sheetName: xls_path, type: 40});
    }
    if (dts_List6.getRowCount() > 0) {
        $c.data.downloadGridViewExcel(grd_List6, {fileName: "매매거래정지", sheetName: xls_path, type: 40});
    }
};

/**
 * @method
 * @name chkIsClose
 * @description 마감가능여부 체크
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.chkIsClose = async function() {
    let isCheck = true;
    let curDd = $c.ut.cGetToday("yyyymmdd");
    let searchDate = edt_ConfirmDate.getValue();
    if (curDd !== searchDate || scwin.vSearchDate !== curDd) {
        await $c.win.alert("당일날짜만 마감가능합니다. 마감일을 확인하세요");
        isCheck = false;
    }
    return isCheck;
};

/**
 * @method
 * @name revw
 * @description 담당자 확인 버튼 클릭시
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.revw = async function() {
    procJob = "담당자 확인";
    if (await scwin.chkIsClose()) {
        let res = window.confirm(procJob + " 마감처리 하시겠습니까?");
        if (res) {
            await scwin.trsRevw();
        }
    }
};

/**
 * @method
 * @name aprv
 * @description 팀장승인 버튼 클릭시
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.aprv = async function() {
    if (loading1 && loading2 && loading3 && loading4 && loading5 && loading6) {
        if (await scwin.chkIsClose()) {
            procJob = "팀장승인";
            if (txb_CONFRM_DDTM.getValue() === "") {
                await $c.win.alert("담당자확인 완료 후 승인처리 가능합니다.");
                return false;
            } else {
                let res = window.confirm(procJob + " 마감처리 하시겠습니까?");
                if (res) {
                    await scwin.trsAprv();
                }
            }
        }
    } else {
        await $c.win.alert("데이터가 로딩중입니다. 로딩후에 승인가능합니다.");
    }
};

/**
 * @method
 * @name buttonSetDis
 * @description 담당자 승인, 팀장승인
 * @returns {void}
 * @hidden N
 */
scwin.buttonSetDis = function() {
    // 담당자일때
    if (scwin.pJobTitl === "03") {
        if (txb_CONFRM_DDTM.getValue() !== "") {
            btn_Revw.setBackgroundImage("../img/btn/btn_revw_d.gif");
            btn_Revw.setDisabled(true);
            btn_BosApv.setBackgroundImage("../img/btn_BosApv_d.gif");
            btn_BosApv.setDisabled(true);
        } else {
            btn_Revw.setBackgroundImage("../img/btn/btn_revw.gif");
            btn_Revw.setDisabled(false);
            btn_BosApv.setBackgroundImage("../img/btn_BosApv_d.gif");
            btn_BosApv.setDisabled(true);
        }
    } else {
        // 팀장일때 - 마감처리
        if (txb_CONFRM_DDTM.getValue() !== "") {
            btn_Revw.setBackgroundImage("../img/btn/btn_revw_d.gif");
            btn_Revw.setDisabled(true);
        } else {
            btn_Revw.setBackgroundImage("../img/btn/btn_revw.gif");
            btn_Revw.setDisabled(false);
        }
        if (txb_APPROV_DDTM.getValue() !== "") {
            btn_BosApv.setBackgroundImage("../img/btn_BosApv_d.gif");
            btn_BosApv.setDisabled(true);
        } else {
            btn_BosApv.setBackgroundImage("../img/btn_BosApv.gif");
            btn_BosApv.setDisabled(false);
        }
    }
};

/**
 * @method
 * @name buttonSetNoData
 * @description 담당자 확인 불가처리
 * @returns {void}
 * @hidden N
 */
scwin.buttonSetNoData = function() {
    btn_Revw.setBackgroundImage("../img/btn/btn_revw_d.gif");
    btn_Revw.setDisabled(true);
};

/**
 * @method
 * @name closeLoading
 * @description close Loading 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.closeLoading = async function() {
    if (loading1 && loading2 && loading3 && loading4 && loading5 && loading6) {
        if ($c.frame.path("LoadingImg") !== null) {
            await $c.win.closePopup();
        }
        await scwin.checkDupList();
    }
};

/**
 * @method
 * @name checkDupList
 * @description 각 단계별 중복종목 리스트 체크
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkDupList = async function() {
    if (!scwin.loopDataSet(dts_List1)) {
        await $c.win.alert("투자유의종목 최초적출 단계에 중복된 종목이 있습니다. 확인하시기 바랍니다.");
    }
    if (!scwin.loopDataSet(dts_List2)) {
        await $c.win.alert("투자유의종목 지정예고 단계에 중복된 종목이 있습니다. 확인하시기 바랍니다.");
    }
    if (!scwin.loopDataSet(dts_List3)) {
        await $c.win.alert("투자유의종목 지정연장 단계에 중복된 종목이 있습니다. 확인하시기 바랍니다.");
    }
    if (!scwin.loopDataSet(dts_List4)) {
        await $c.win.alert("투자유의종목 지정 단계에 중복된 종목이 있습니다. 확인하시기 바랍니다.");
    }
    if (!scwin.loopDataSet(dts_List5)) {
        await $c.win.alert("투자유의종목 지정해제 단계에 중복된 종목이 있습니다. 확인하시기 바랍니다.");
    }
    if (!scwin.loopDataSet(dts_List6)) {
        await $c.win.alert("투자유의종목 매매거래정지 단계에 중복된 종목이 있습니다. 확인하시기 바랍니다.");
    }
};

/**
 * @method
 * @name loopDataSet
 * @description loop Data Set 처리
 * @param {String} dtsId dtsId
 * @returns {void}
 * @hidden N
 */
scwin.loopDataSet = function(dtsId) {
    let tempData = "";
    let checkData = "";
    for (let i = 1, j = dtsId.getRowCount(); i <= j; i++) {
        tempData = dtsId.getCellData(i, "ISU_CD");
        for (let k = 1, l = dtsId.getRowCount(); k <= l; k++) {
            if (i === k) {
                continue;
            }
            checkData = dtsId.getCellData(k, "ISU_CD");
            if (tempData === checkData) {
                return false;
            }
        }
    }
    return true;
};
